parameters.jsonBody:
={
  "model": "mistral:7b",
  "prompt": "Parse this Indian bank email and return ONLY a JSON array. Format: [{amount: number, currency: INR, transaction_type: DEBIT/CREDIT/TRANSFER, merchant_name: brand name or null, merchant_upi: upi@id or null, bank_name: bank, account_last4: 4 digits or null, category: groceries/transport/food/entertainment/medical/utilities/shopping/rent/salary/transfer/insurance/emi/other, date: YYYY-MM-DD, time: HH:MM or null}]. Rules: amount no commas/symbols, merchant_name clean brand, null for missing. ONLY JSON array.\n\nEmail: {{ $('Sample Bank Email').first().json.email_text }}",
  "stream": false,
  "options": {"temperature": 0.1, "num_predict": 300}
}
